// Hard rules from CLAUDE.md §5.2, checked in order. Business hours from §8.
const ZONE = 'America/New_York';
const WINDOW_STARTS = [8, 10, 12, 14, 16];
const WARRANTY_BRANDS = ['lg', 'samsung', 'ge', 'general electric'];
const REQUIRED = ['customer_name', 'phone', 'service_address', 'appliance_type', 'brand', 'issue_description', 'is_warranty', 'slot_start'];

const body = $input.first().json.body ?? {};
const a = body.args ?? body;
const text = v => (v === undefined || v === null) ? '' : String(v).trim();
const bool = v => v === true || text(v).toLowerCase() === 'true';
const reject = reason => [{ json: { valid: false, reason } }];

// "Use the number I'm calling from": if the agent sent no usable number, use the caller ID Retell
// attached to the request; with no caller ID either, the phone counts as missing.
if (text(a.phone).replace(/\D/g, '').length < 7) a.phone = body.call?.from_number ?? '';

for (const field of REQUIRED) {
  if (text(a[field]) === '') return reject('missing_field:' + field);
}

const isWarranty = bool(a.is_warranty);
const feeAccepted = bool(a.fee_accepted);
const brandKey = text(a.brand).toLowerCase().replace(/[^a-z ]/g, '').replace(/\s+/g, ' ').trim();
if (isWarranty && !WARRANTY_BRANDS.includes(brandKey)) return reject('brand_not_covered_for_warranty');
if (!isWarranty && !feeAccepted) return reject('fee_not_accepted');

// The slot must be a real future window; a taken slot is checked against the table next.
const start = DateTime.fromISO(text(a.slot_start), { zone: ZONE });
const isWindow = start.isValid && start.weekday <= 5 && WINDOW_STARTS.includes(start.hour)
  && start.minute === 0 && start.second === 0 && start > DateTime.now().setZone(ZONE);
if (!isWindow) return reject('slot_unavailable');

const customerName = text(a.customer_name);
const applianceType = text(a.appliance_type);
const brand = text(a.brand);
return [{ json: { valid: true, booking: {
  slot_start: start.toISO({ suppressMilliseconds: true }),
  booking_id: 'BK-' + DateTime.now().setZone(ZONE).toFormat('yyMMdd') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase(),
  title: (isWarranty ? 'Warranty' : 'Paid') + ' repair: ' + applianceType + ' (' + brand + ') — ' + customerName,
  customer_name: customerName,
  phone: text(a.phone),
  service_address: text(a.service_address),
  appliance_type: applianceType,
  brand: brand,
  issue_description: text(a.issue_description),
  is_warranty: isWarranty,
  fee_accepted: feeAccepted,
  fee: isWarranty ? 'warranty: no fee' : '$99',
  created_at: DateTime.now().toISO()
} } }];

// Retell signs each request: x-retell-signature = "v=<ms timestamp>,d=<hex>",
// hex = HMAC-SHA256(raw_body + timestamp) keyed with the Retell API key that has the webhook badge.
// The key lives in the n8n Variable RETELL_API_KEY so it never appears in the workflow export.
const crypto = require('crypto');
const MAX_AGE_MS = 5 * 60 * 1000;

const item = $input.first();
const headers = item.json.headers ?? {};
const header = String(headers['x-retell-signature'] ?? '');
const key = $vars.RETELL_API_KEY ?? '';

let raw = '';
if (item.binary?.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
}
let body = item.json.body;
if ((!body || Object.keys(body).length === 0) && raw) {
  try { body = JSON.parse(raw); } catch (e) { body = {}; }
}

let ok = false;
const match = /^v=(\d+),d=([0-9a-f]+)$/i.exec(header);
if (key && raw && match && Math.abs(Date.now() - Number(match[1])) <= MAX_AGE_MS) {
  const expected = crypto.createHmac('sha256', key).update(raw + match[1]).digest('hex');
  const a = Buffer.from(expected, 'hex');
  const b = Buffer.from(match[2], 'hex');
  ok = a.length === b.length && crypto.timingSafeEqual(a, b);
}

return [{ json: { signature_ok: ok, body } }];
